--- /dev/null
+++ b/repro-19245/input.js
@@ -0,0 +1,14 @@
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+
+function unsafeFn() {
+  throw new Error();
+}
diff --git a/repro-19245/repro.js b/repro-19245/repro.js
new file mode 100644
index 0000000..405d716
--- /dev/null
+++ b/repro-19245/repro.js
@@ -0,0 +1,53 @@
+"use strict";
+// Reproduction for eslint/eslint#19245: no-useless-assignment false positive in try/catch.
+const assert = require("node:assert");
+const fs = require("node:fs");
+const path = require("node:path");
+const { Linter } = require("../lib/api");
+
+const linter = new Linter();
+const config = { rules: { "no-useless-assignment": "warn" } };
+
+const cases = {
+    // Reporter's exact code: try block ends with `return`.
+    reported: fs.readFileSync(path.join(__dirname, "input.js"), "utf8"),
+    // Variant: try block ends with `break` instead of `return`.
+    breakInTry: `
+function fn() {
+  let v;
+  for (;;) {
+    try {
+      v = 42;
+      unsafeFn();
+      break;
+    } catch {
+      return v;
+    }
+  }
+}`,
+    // Control: same code without `return` in the try block.
+    noReturnInTry: `
+function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+  } catch {
+    return { intermediaryValue };
+  }
+}`
+};
+
+let failed = false;
+for (const [name, code] of Object.entries(cases)) {
+    const messages = linter.verify(code, config).filter(m => m.ruleId === "no-useless-assignment");
+    console.log(`[${name}] ${messages.length} report(s)`);
+    for (const m of messages) console.log(`  ${m.line}:${m.column} ${m.message}`);
+    try {
+        assert.strictEqual(messages.length, 0, `${name}: expected no reports`);
+    } catch (e) {
+        failed = true;
+        console.log(`  FAIL: ${e.message}`);
+    }
+}
+process.exitCode = failed ? 1 : 0;
